const S=[["AUD-1042","Studio wireless headphones","Audio","A-03-2",148,40,"1505740420928-5e560c06d30e"],["AUD-1077","Noise-cancel earbuds","Audio","A-04-1",22,50,"1606220588913-b3aacb4d2f46"],["WEA-2210","Nord minimal watch","Wearables","B-01-4",6,30,"1523275335684-37898b6baf30"],["ACC-3301","Wireless mouse","Accessories","C-02-1",0,25,"1527864550417-7fd91fc51a46"],["HOM-4108","Insulated steel bottle","Home","D-05-3",310,80,"1602143407151-7111542de6e8"],["ACC-3315","Travel backpack","Accessories","C-06-2",64,30,"1553062407-98eeb64c6a62"],["AUD-1090","Over-ear headphones, black","Audio","A-02-6",35,40,"1583394838336-acd977736f90"]];
const st=it=>it[4]===0?'out':it[4]<=it[5]?'low':'ok',lab={ok:'In stock',low:'Low stock',out:'Out of stock'};
function draw(){const q=document.getElementById('q').value.toLowerCase(),c=document.getElementById('cat').value,s=document.getElementById('st').value;
document.getElementById('stock').innerHTML=S.map((it,i)=>[it,i]).filter(([it])=>(!q||(it[0]+it[1]).toLowerCase().includes(q))&&(!c||it[2]===c)&&(!s||st(it)===s)).map(([it,i])=>{const k=st(it),p=Math.min(100,it[4]/(it[5]*3)*100);return `<tr><td class="sku">${it[0]}</td><td><div class="item"><img src="https://images.unsplash.com/photo-${it[6]}?w=80&q=60&auto=format&fit=crop" alt="" width="38" height="38" loading="lazy">${it[1]}</div></td><td>${it[2]}</td><td>${it[3]}</td><td><div class="qty"><button type="button" data-i="${i}" data-d="-1" aria-label="Remove one ${it[1]}">−</button><span>${it[4]}</span><button type="button" data-i="${i}" data-d="1" aria-label="Add one ${it[1]}">+</button></div></td><td><div class="lvl"><i style="width:${p}%;background:${k==='ok'?'#12805C':k==='low'?'#FFC400':'#D92D20'}"></i></div></td><td><span class="chip ${k}">${lab[k]}</span></td></tr>`}).join('')||'<tr><td colspan="7">No items match.</td></tr>';
document.getElementById('lowc').textContent=S.filter(it=>st(it)!=='ok').length;
const r=S.filter(it=>st(it)!=='ok');document.getElementById('re').innerHTML=r.map(it=>`<div class="re"><span>${it[1]}<br><small style="color:var(--muted)">Order ${it[5]*3-it[4]} units</small></span><button type="button">Create PO</button></div>`).join('')||'<p style="color:var(--muted);font-size:14px">Nothing to reorder.</p>'}
document.getElementById('stock').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const it=S[b.dataset.i];it[4]=Math.max(0,it[4]+ +b.dataset.d);draw()});
document.getElementById('re').addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){e.target.textContent='PO created';e.target.disabled=true}});
['q','cat','st'].forEach(id=>document.getElementById(id).addEventListener('input',draw));draw();
function mv(){const s=document.getElementById('mv'),w=s.clientWidth||360,h=200,pl=30,pb=20,IN=[220,0,180,340,120,0,260,300,90,210,0,380,160,240],OUT=[180,160,210,190,230,120,200,240,220,190,140,260,230,250],mx=400,bw=(w-pl)/IN.length;let o='';
[0,200,400].forEach(v=>{const y=h-pb-v/mx*(h-pb-10);o+=`<line x1="${pl}" x2="${w}" y1="${y}" y2="${y}" stroke="#E3E4E6"/><text x="${pl-5}" y="${y+4}" text-anchor="end" font-size="10" fill="#6B7078">${v}</text>`});
IN.forEach((v,i)=>{const x=pl+i*bw+bw*.15,y1=h-pb-v/mx*(h-pb-10),y2=h-pb-OUT[i]/mx*(h-pb-10);o+=`<rect x="${x}" y="${y1}" width="${bw*.34}" height="${h-pb-y1}" fill="#FFC400"/><rect x="${x+bw*.36}" y="${y2}" width="${bw*.34}" height="${h-pb-y2}" fill="#1B1D21"/>`});
o+=`<text x="${pl}" y="${h-4}" font-size="10" fill="#B38900">■ received</text><text x="${pl+80}" y="${h-4}" font-size="10" fill="#1B1D21">■ shipped</text>`;s.setAttribute('viewBox',`0 0 ${w} ${h}`);s.innerHTML=o}
mv();window.addEventListener('resize',mv);
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
